import React, { useState } from 'react';
import axios from 'axios';
import './Prediction.css';

function Prediction() {
  const [formData, setFormData] = useState({
    age: 30,
    gender: 'Female',
    bmi: 25.0,
    hbA1c_level: 5.7,
    blood_glucose_level: 120,
    hypertension: 0,
    heart_disease: 0,
    smoking_history: 'never'
  });
  
  const [prediction, setPrediction] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (checked ? 1 : 0) : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    setPrediction(null);
    
    try {
      const response = await axios.post('http://localhost:8000/predict', formData, {
        headers: {
          'Content-Type': 'application/json'
        }
      });
      setPrediction(response.data);
    } catch (err) {
      const errorMsg = err.response?.data?.detail || 'Prediction failed. Please try again.';
      setError(errorMsg);
      console.error("Prediction error:", err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="prediction-container">
      <h2>Diabetes Risk Prediction</h2>
      
      <form onSubmit={handleSubmit}>
        <div className="form-grid">
          <div className="form-group">
            <label>Age:</label>
            <input
              type="number"
              name="age"
              value={formData.age}
              onChange={handleChange}
              min="0"
              max="120"
              step="1"
              required
            />
          </div>
          
          <div className="form-group">
            <label>Gender:</label>
            <select
              name="gender"
              value={formData.gender}
              onChange={handleChange}
              required
            >
              <option value="Female">Female</option>
              <option value="Male">Male</option>
              <option value="Other">Other</option>
            </select>
          </div>
          
          <div className="form-group">
            <label>BMI:</label>
            <input
              type="number"
              name="bmi"
              value={formData.bmi}
              onChange={handleChange}
              min="10"
              max="50"
              step="0.1"
              required
            />
          </div>
          
          <div className="form-group">
            <label>HbA1c Level (%):</label>
            <input
              type="number"
              name="hbA1c_level"
              value={formData.hbA1c_level}
              onChange={handleChange}
              min="3"
              max="15"
              step="0.1"
              required
            />
          </div>
          
          <div className="form-group">
            <label>Blood Glucose Level (mg/dL):</label>
            <input
              type="number"
              name="blood_glucose_level"
              value={formData.blood_glucose_level}
              onChange={handleChange}
              min="50"
              max="300"
              step="1"
              required
            />
          </div>
          
          <div className="form-group checkbox">
            <label>
              <input
                type="checkbox"
                name="hypertension"
                checked={formData.hypertension === 1}
                onChange={handleChange}
              />
              Hypertension
            </label>
          </div>
          
          <div className="form-group checkbox">
            <label>
              <input
                type="checkbox"
                name="heart_disease"
                checked={formData.heart_disease === 1}
                onChange={handleChange}
              />
              Heart Disease
            </label>
          </div>
          
          <div className="form-group">
            <label>Smoking History:</label>
            <select
              name="smoking_history"
              value={formData.smoking_history}
              onChange={handleChange}
              required
            >
              <option value="never">Never</option>
              <option value="former">Former</option>
              <option value="current">Current</option>
              <option value="not current">Not Current</option>
              <option value="ever">Ever</option>
            </select>
          </div>
        </div>
        
        <button type="submit" disabled={isLoading} className="submit-btn">
          {isLoading ? 'Predicting...' : 'Get Prediction'}
        </button>
      </form>
      
      {error && <div className="error-message">{error}</div>}
      
      {prediction && (
        <div className={`prediction-result ${prediction.prediction ? 'high-risk' : 'low-risk'}`}>
          <h3>Prediction Result</h3>
          <p><strong>Risk Level:</strong> {prediction.interpretation}</p>
          <p><strong>Probability:</strong> {(prediction.probability * 100).toFixed(1)}%</p>
          <p className="recommendation">
            {prediction.prediction 
              ? "We recommend consulting with a healthcare professional for further evaluation." 
              : "Maintain healthy habits to keep your risk low."}
          </p>
        </div>
      )}
    </div>
  );
}

export default Prediction;
